from functools import partial

from taf.rfrl.bts.connections.device_aliases import ssh_bts_du
from taf.rfrl.utilities.logger.custom_logger import log_info_to_console, log_warn_to_console
from taf.rfrl.utilities.robot.RobotKWRunner import run_as_robot_kw as convert_to_robot_kw
from taf.rfrl.utilities.robot.RobotThreads import RobotThreads
from taf.rfrl.utilities.robot.RobotWrapper import RobotWrapper


class GenericKPIMultiBTSEx(object):

    def create_other_bts_objects(self):
        if self.multi_bts_dict:
            for bts in self.multi_bts_dict.keys():
                if "excluded_functions" not in self.multi_bts_dict[bts].keys():
                    self.multi_bts_dict[bts]["excluded_functions"] = ["run_operation"]
                    self.multi_bts_dict[bts]["kwargs"]["calculate_kpi"] = False
                bts_object = type(self)(multi_bts_dict=True, **self.multi_bts_dict[bts]["kwargs"])
                bts_object.custom_logger = self.multi_bts_logger(bts_object)
                self.multi_bts_dict[bts]["object"] = bts_object
            self.custom_logger = self.multi_bts_logger(self)
            self.actions_before_loop = self.multi_bts_decorator(self.actions_before_loop)
            self.run_preconditions = self.multi_bts_decorator(self.run_preconditions)
            self.checks_before_operation = self.multi_bts_decorator(self.checks_before_operation)
            self.actions_before_operation = self.multi_bts_decorator(self.actions_before_operation)
            self.run_operation = self.multi_bts_decorator(self.run_operation)
            self.actions_after_operation = self.multi_bts_decorator(self.actions_after_operation)
            self.checks_after_operation = self.custom_checks_after_operation
            self.actions_when_bts_did_not_go_on_air = self.custom_checks_after_operation
            self.run_postconditions = self.multi_bts_decorator(self.run_postconditions)
            self.check_status_after_run = self.multi_bts_decorator(self.check_status_after_run,
                                                                   pre_function="sync_iterations_pre_function")
            self.actions_after_loop = self.multi_bts_decorator(self.actions_after_loop, robot_type=False)

    def custom_checks_after_operation(self, timeout):
        bts_statuses = self.check_onair(timeout=timeout)
        if all(bts_statuses.values()):
            return True
        try:
            initial = self.delay_for_checking_onAir
            wait_to_23_minutes = 25 * 60 - int(timeout) if timeout < 1380 else int(timeout * 0.25)
            bts_on_air, bts_not_onair = self.split_bts_statuses(bts_statuses)
            log_info_to_console("Waiting {} for {} to automatic BTS recovery".format(wait_to_23_minutes,
                                                                                     ", ".join(bts_not_onair)))
            from_not_on_air_to_on_air, from_not_on_air_to_not_on_air = \
                self.split_bts_statuses(self.check_onair(timeout=wait_to_23_minutes, bts_to_check=bts_not_onair))
            from_on_air_ton_on_air, from_on_air_to_not_on_air = [], []
            if bts_on_air:
                from_on_air_ton_on_air, from_on_air_to_not_on_air = \
                    self.split_bts_statuses(self.check_onair(timeout=10 + initial, bts_to_check=bts_on_air))
            bts_not_onair = from_not_on_air_to_not_on_air + from_on_air_to_not_on_air
            bts_onair = from_on_air_ton_on_air + from_not_on_air_to_on_air
            if not bts_not_onair:
                return True
            self.actions_when_bts_not_onair(timeout=timeout, bts_onair=bts_onair, bts_not_onair=bts_not_onair)
        finally:
            self._run_robot_kw_for_all_bts(self._fail_iteration)

    @staticmethod
    def split_bts_statuses(bts_statuses):
        bts_not_onair = [bts for bts in bts_statuses.keys() if bts_statuses[bts] is False]
        bts_on_air = [bts for bts in bts_statuses.keys() if bts_statuses[bts] is True]
        return bts_on_air, bts_not_onair

    def check_onair(self, timeout, bts_to_check=[]):
        target_func = self.wait_for_all_cells_onair
        functions = self.create_functions_for_other_bts(wanted_args={"timeout": timeout}, target_func=target_func)
        with RobotThreads() as threads:
            for bts_name, function in functions.items():
                if bts_to_check and bts_name not in bts_to_check:
                    continue
                threads.create_thread(thread_name="Check_OnAir_Thread_{}".format(bts_name), function=function)
            main_bts_name = ssh_bts_du.format(self.bts_type, self.bts_id, self.du_id)
            if not bts_to_check or main_bts_name in bts_to_check:
                custom_repr_name = self._get_custom_repr_name(func=target_func)
                main_thread_return = convert_to_robot_kw(partial(target_func), timeout=timeout,
                                                         custom_repr_name=custom_repr_name)
                threads.thread_results["Check_OnAir_Thread_{}".format(main_bts_name)] = main_thread_return
        return {thread.split("Thread_")[-1]: threads.thread_results[thread]
                for thread in threads.thread_results.keys()}

    def actions_when_bts_not_onair(self, timeout, bts_not_onair=[], bts_onair=[]):
        with RobotWrapper(wrap_name="BTS RECOVERY LOOP, ITERATIONS: {}".format(self._recover_reset_amount + 1),
                          wrap_type="for") as wrapper:
            for attempt in range(1, self._recover_reset_amount + 1):
                wrapper.create_level("RECOVERY ATTEMPT = {}".format(attempt), wrap_type="foritem", level=2)
                if attempt == 1:
                    bts_status = self.custom_recover_bts(bts_not_onair=bts_not_onair, bts_onair=bts_onair,
                                                         timeout=timeout)
                else:
                    bts_status = self.custom_recover_bts(bts_not_onair=bts_not_onair + bts_onair, bts_onair=[],
                                                         timeout=timeout)
                if not bts_not_onair:
                    log_info_to_console("All BTS on-air")
                    break
                self._run_robot_kw_for_all_bts(self._verify_alarms)
                bts_onair, bts_not_onair = self.split_bts_statuses(bts_statuses=bts_status)
                if attempt != self._recover_reset_amount:
                    self.custom_logger(log_info_to_console, msg="Sleep for 23 min, before next try to recover bts",
                                       log_hierarchy=3)
                    convert_to_robot_kw(self._sleep, sleep_time=23 * 60)
            else:
                self._run_robot_kw_for_all_bts(self.collect_logs_after_fail)
                self._run_robot_kw_for_all_bts(self._stop_collecting_logs)
                self.custom_logger(log_warn_to_console, msg="SITE WERE UNABLE TO RECOVER AFTER {} TRIES, SLEEP FOR 72H".
                                   format(self._recover_reset_amount), log_hierarchy=4)
                convert_to_robot_kw(self._sleep, sleep_time=60 * 60 * 72)

    def custom_recover_bts(self, timeout, bts_onair, bts_not_onair):
        target_recover_func = self._recover_bts
        target_collect_logs_func = self.collect_logs_after_fail
        recover_func = self.create_functions_for_other_bts(target_func=target_recover_func,
                                                           wanted_args={"timeout": timeout})
        snap_func = self.create_functions_for_other_bts(target_func=target_collect_logs_func)
        with RobotThreads() as threads:
            for bts_name in snap_func.keys():
                if bts_name in bts_not_onair:
                    threads.create_thread(thread_name="RecoveryBTS_Thread_{}".format(bts_name),
                                          function=recover_func[bts_name])
                else:
                    threads.create_thread(thread_name="RecoveryBTS_Thread_{}".format(bts_name),
                                          function=snap_func[bts_name])
            main_bts_name = ssh_bts_du.format(self.bts_type, self.bts_id, self.du_id)
            if main_bts_name in bts_not_onair:
                custom_repr_name = self._get_custom_repr_name(func=target_recover_func)
                main_thread_return = convert_to_robot_kw(partial(target_recover_func),
                                                         timeout=timeout, custom_repr_name=custom_repr_name)
            else:
                custom_repr_name = self._get_custom_repr_name(func=target_collect_logs_func)
                main_thread_return = convert_to_robot_kw(partial(target_collect_logs_func),
                                                         custom_repr_name=custom_repr_name)
            threads.thread_results["RecoveryBTS_Thread_{}".format(main_bts_name)] = main_thread_return
        bts_statuses = self.check_onair(timeout=timeout, bts_to_check=bts_onair)
        for thread_name in threads.thread_results.keys():
            bts_name = thread_name.split("Thread_")[-1]
            if bts_name in bts_not_onair:
                bts_statuses[bts_name] = threads.thread_results[thread_name]
        return bts_statuses

    @staticmethod
    def multi_bts_logger(bts_object):

        def logger(logger_func, *args, **kwargs):
            bts_name = ssh_bts_du.format(bts_object.bts_type, bts_object.bts_id, bts_object.du_id)
            kwargs["msg"] = bts_name + " - " + kwargs["msg"]
            convert_to_robot_kw(logger_func, *args, **kwargs)

        return logger

    def create_functions_for_other_bts(self, target_func, wanted_args={}, robot_type=True):
        functions = {}
        for bts in self.multi_bts_dict.keys():
            if target_func.__name__ not in self.multi_bts_dict[bts]["excluded_functions"]:
                bts_object = self.multi_bts_dict[bts]["object"]
                other_bts_kwargs = self._get_full_kwargs(bts_object=bts_object, wanted_args=wanted_args)
                try:
                    func = getattr(bts_object, target_func.__name__)
                except AttributeError:
                    func = target_func
                bts_name = ssh_bts_du.format(bts_object.bts_type, bts_object.bts_id, bts_object.du_id)
                if robot_type is True:
                    custom_repr_name = bts_name + "." + self.__class__.__name__ + "." + target_func.__name__
                    func = partial(convert_to_robot_kw, func, **other_bts_kwargs, custom_repr_name=custom_repr_name)
                else:
                    func = partial(func, **other_bts_kwargs)
                functions[bts_name] = func
        return functions

    @staticmethod
    def _get_full_kwargs(bts_object, wanted_args):
        full_kwargs = {}
        bts_attrs = dir(bts_object)
        for attr in list(wanted_args):
            if attr not in bts_attrs:
                full_kwargs[attr] = wanted_args[attr]
            else:
                full_kwargs[attr] = getattr(bts_object, attr)
        return full_kwargs

    def multi_bts_decorator(self, target_func, robot_type=True, pre_function=None):

        def multi_bts_action(**kwargs):
            if self.multi_bts_dict:
                functions = self.create_functions_for_other_bts(wanted_args=kwargs, target_func=target_func,
                                                                robot_type=robot_type)
                if pre_function is not None:
                    convert_to_robot_kw(getattr(self, pre_function))

                def multi_bts_runner():
                    with RobotThreads() as threads:
                        for thread_num, function in enumerate(functions.values()):
                            threads.create_thread(thread_name="Thread_KPI_{}".format(thread_num), function=function)
                        if robot_type is True:
                            custom_repr_name = self._get_custom_repr_name(func=target_func)
                            main_thread_return = convert_to_robot_kw(partial(target_func), **kwargs,
                                                                     custom_repr_name=custom_repr_name)
                        else:
                            main_thread_return = target_func(**kwargs)
                        threads.thread_results["MainThread"] = main_thread_return
                    return threads.thread_results.values()

                return multi_bts_runner()

            return target_func(**kwargs)

        multi_bts_action.__name__ = target_func.__name__
        return multi_bts_action

    def sync_iterations_pre_function(self):
        if any([bts_object["object"]._current_status == "FAILED" for bts_object in self.multi_bts_dict.values()]) or \
                self._current_status == "FAILED":
            for bts_object in self.multi_bts_dict.values():
                bts_object["object"]._current_status = "FAILED"
            self._current_status = "FAILED"

    def _get_custom_repr_name(self, func):
        bts_name = ssh_bts_du.format(self.bts_type, self.bts_id, self.du_id)
        return bts_name + "." + self.__class__.__name__ + "." + func.__name__

    def _run_robot_kw_for_all_bts(self, target_method):
        target_method_multi = self.multi_bts_decorator(target_method)
        convert_to_robot_kw(target_method_multi)
